t.script:
(function () {
  "use strict";
  function $(sel, root){ return (root||document).querySelector(sel); }
  function $val(id, d){ var el=$("#"+id); return el?el.value:d; }

  // Carga imagen sin crossOrigin (iOS no taints el canvas)
  function loadImage(src){
    return new Promise(function(resolve, reject){
      var im=new Image();
      im.onload=function(){ resolve(im); };
      im.onerror=reject;
      im.src=src;
    });
  }
  function readAsDataURL(file){
    return new Promise(function(resolve, reject){
      var r=new FileReader();
      r.onload=function(){ resolve(r.result); };
      r.onerror=reject;
      r.readAsDataURL(file);
    });
  }
  function dataURLtoBase64(u){
    var i=u.indexOf(','); return i!==-1?u.slice(i+1):u;
  }

  var S={ logoDataURL:"", isSVG:false };

  function applyTransform(){
    var logo=$("#spw_logo_preview"); if(!logo) return;
    var size=parseInt($val("spw_size","100"),10);
    var posX=parseInt($val("spw_pos_x","0"),10);
    var posY=parseInt($val("spw_pos_y","10"),10);
    var rot =parseInt($val("spw_rotation","0"),10);
    var tx=-50+posX, ty=-50+posY;
    logo.style.transform="translate("+tx+"%,"+ty+"%) rotate("+rot+"deg)";
    logo.style.width=size+"px";
  }

  async function renderPNGDataURL(){
    var baseSrc=$val("spw_img_src","") || ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin imagen base.");
    var baseIm=await loadImage(baseSrc);

    var canvas=document.createElement("canvas");
    var ctx=canvas.getContext("2d");
    canvas.width=baseIm.naturalWidth||baseIm.width;
    canvas.height=baseIm.naturalHeight||baseIm.height;

    // base
    ctx.drawImage(baseIm,0,0,canvas.width,canvas.height);

    // logo
    if(S.logoDataURL){
      var sizePx=parseInt($val("spw_size","100"),10);
      var posX=parseInt($val("spw_pos_x","0"),10);
      var posY=parseInt($val("spw_pos_y","10"),10);
      var rot =(parseInt($val("spw_rotation","0"),10)*Math.PI)/180;

      var cx=canvas.width*0.5 + (posX/100)*canvas.width;
      var cy=canvas.height*0.6 + (posY/100)*canvas.height;

      var logoIm=await loadImage(S.logoDataURL);
      var ratio=logoIm.naturalWidth ? (sizePx / logoIm.naturalWidth) : 1;
      var w=logoIm.naturalWidth * ratio, h=logoIm.naturalHeight * ratio;

      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot);
      ctx.drawImage(logoIm,-w/2,-h/2,w,h);
      ctx.restore();
    }
    return canvas.toDataURL("image/png");
  }

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim();
    var qty=parseInt($val("spw_qty","1"),10)||1;
    var tech=( ($("input[name='spw_tech']:checked")||{}).value )||"";
    var svgColor=( ($("input[name='spw_svg_color']:checked")||{}).value )||"";
    var notes=($val("spw_notes","")||"").trim();
    if(!variantId){ alert("Falta la variante del producto."); return; }

    var pngB64="";
    try{ pngB64 = dataURLtoBase64(await renderPNGDataURL()); }catch(e){}

    var payload={ variant_id:parseInt(variantId,10), qty:qty, tech:tech, svg_color:svgColor, notes:notes, png_b64:pngB64 };

    async function tryPost(url){
      var resp = await fetch(url,{
        method:"POST",
        headers:{ "Content-Type":"application/json", "X-Requested-With":"XMLHttpRequest" },
        body: JSON.stringify(payload),
        credentials:"same-origin"
      });
      var txt = await resp.text(); var json=null;
      try{ json = JSON.parse(txt); }catch(e){}
      return {ok: resp.ok && json && (json.ok===true || json.ok==="true"), data: json};
    }

    // JSON y fallback HTTP si existe en tu main.py
    var r = await tryPost("/spw/add_to_cart");
    if(!(r.ok)) r = await tryPost("/spw/add_to_cart_http");
    if(r.ok && r.data){ window.location.href = r.data.cart_url || "/shop/cart"; }
    else{ alert("No se pudo añadir al carrito."); }
  }

  function init(){
    var logoInput=$("#spw_logo_input");
    var logoEl=$("#spw_logo_preview");
    if(logoInput){
      logoInput.addEventListener("change", async function(ev){
        var f = ev.target.files && ev.target.files[0]; if(!f) return;
        var name=(f.name||"").toLowerCase(); S.isSVG = name.endsWith(".svg");
        var dataURL = await readAsDataURL(f);
        S.logoDataURL = dataURL;
        logoEl.src = dataURL; logoEl.classList.remove("d-none"); logoEl.style.opacity = "1";
        applyTransform();
      });
    }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){
      var el=$("#"+id); if(el) el.addEventListener("input", applyTransform);
    });
    window.spwReset=function(){ $("#spw_size").value=100; $("#spw_pos_x").value=0; $("#spw_pos_y").value=10; $("#spw_rotation").value=0; applyTransform(); };

    var dl=$("#spw_download_png");
    if(dl){ dl.addEventListener("click", async function(){
      try{
        var url = await renderPNGDataURL();
        var a = document.createElement("a");
        a.href=url; a.download="personalizacion.png";
        document.body.appendChild(a); a.click(); a.remove();
      }catch(e){ alert("No se pudo generar el PNG."); }
    });}

    var add=$("#spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }

    applyTransform();
  }

  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();
